from batch07 import *
start('fhrp','Redundancja bramy — HSRP','3.5',['https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipapp_fhrp/configuration/xe-16-12/fhp-xe-16-12-book/fhp-hsrp.html','https://www.cisco.com/c/en/us/support/docs/ip/hot-standby-router-protocol-hsrp/13780-6.html','https://www.cisco.com/c/en/us/support/docs/ip/hot-standby-router-protocol-hsrp/9234-hsrpguidetoc.html'])
q('Wspólna brama','Jakie IP host powinien mieć jako bramę w poprawnie zaprojektowanej grupie HSRP?','Wirtualny adres IP grupy',['Fizyczne IP wyłącznie obecnego active|To uzależnia hosta od jednego urządzenia.','Adres multicast OSPF|Nie jest adresem bramy hosta.','Adres rozgłoszeniowy podsieci|Broadcast nie jest bramą unicast.'],'Wirtualna brama pozwala zmienić aktywny router bez zmiany konfiguracji hostów.')
c('Wirtualny adres','Na interfejsie LAN z adresem 192.168.10.2/24 ustaw VIP grupy 10 na 192.168.10.1. Adres jest wolny.','R1(config-if)# standby 10 ip {{b0}}',[(['192.168.10.1'],'ipv4')],'VIP musi należeć do właściwej podsieci; nie zastępuje indywidualnych adresów routerów.')
c('Priorytet HSRP','Ustaw priorytet 120 w istniejącej grupie 10.','R1(config-if)# standby 10 priority {{b0}}',['120'],'Wyższy priorytet jest preferowany w wyborze active, ale przejęcie działającej roli wymaga uwzględnienia preempt.')
q('Active i standby','Które urządzenie zwykle przekazuje ruch kierowany na wirtualną bramę danej grupy HSRP?','Router w roli active',['Oba zawsze dzielą każdy pakiet po połowie|Jedna grupa HSRP nie działa tak jak per-packet load balancing.','Tylko standby|Standby jest przygotowany do przejęcia roli.','Host o najwyższym MAC|Hosty nie uczestniczą w wyborze routera active.'],'HSRP utrzymuje aktywną bramę i zastępstwo dla jednej grupy.')
c('Powrót preferowanej bramy','Pozwól routerowi o wyższym priorytecie przejąć active od działającego routera o niższym priorytecie.','R1(config-if)# standby 10 {{b0}}',['preempt'],'Preempt umożliwia przejęcie; nie gwarantuje dostępności całej drogi poza bramą.')
c('Skrócony stan HSRP','Wyświetl skróconą tabelę grup HSRP.','R1# show standby {{b0}}',['brief'],'Tabela pozwala sprawdzić rolę, grupę, priorytet i adres wirtualny.')
q('Wysoki priorytet bez preempt','R2 jest active z priorytetem 100. R1 wraca z priorytetem 120, lecz bez preempt. R2 działa poprawnie. Co jest oczekiwane?','R2 może pozostać active',['R1 zawsze natychmiast odbiera rolę|Sam wyższy priorytet nie włącza preempt.','Oba wyłączą interfejs LAN|Nie jest to standardowy skutek różnicy priorytetów.','VIP zmieni się na fizyczny adres R1|VIP nie jest w ten sposób zmieniany.'],'Wyższy priorytet i możliwość wywłaszczenia aktywnego routera to odrębne elementy.')
c('Preferencja i przejęcie','Dla grupy 20 ustaw priorytet 110 oraz preempt.','R1(config-if)# standby 20 priority {{b0}}\nR1(config-if)# standby 20 {{b1}}',['110','preempt'],'Preempt pozwala wykorzystać wyższy priorytet również po powrocie preferowanego routera.')
c('Wersja i grupa','Ustaw HSRPv2 i VIP 10.20.0.1 w grupie 20 na interfejsie 10.20.0.2/24.','R1(config-if)# standby version {{b0}}\nR1(config-if)# standby 20 ip {{b1}}',['2',(['10.20.0.1'],'ipv4')],'Routery w jednej grupie muszą używać zgodnych parametrów HSRP, w tym wersji.')
q('Awaria za bramą','Active nadal widzi LAN, ale utracił uplink. Bez dodatkowego trackingu czego HSRP może nie zauważyć?','Utraty użytecznej ścieżki poza bramą',['Utraty własnych komunikatów hello na LAN|To właśnie jest częścią wykrywania działania sąsiada.','Zmiany adresu VIP przez administratora|To zmiana konfiguracji, a nie opisana awaria.','Liczby znaków w nazwie hosta|Nie ma związku z użytecznością uplinku.'],'Żywa brama w LAN nie oznacza działającej drogi do zdalnego celu; stosuje się właściwie zaprojektowany tracking.')
c('Powiąż obiekt śledzenia','Obiekt track 5 już istnieje. W grupie 10 zmniejsz priorytet o 30 po jego awarii.','R1(config-if)# standby 10 track {{b0}} decrement {{b1}}',['5','30'],'Obniżka musi być wystarczająca względem priorytetu drugiego routera i jego polityki preempt.')
c('Odroczone przejęcie','W grupie 10 ustaw preempt z minimalnym opóźnieniem 60 sekund.','R1(config-if)# standby 10 {{b0}} delay minimum {{b1}}',['preempt','60'],'Opóźnienie daje czas na odbudowę pozostałych funkcji; nie zastępuje sprawdzenia gotowości trasy.')
q('Arytmetyka trackingu','R1 ma priority 120, decrement 30, R2 priority 100 i preempt. Track R1 przechodzi down. Który priorytet ma teraz R1?','90',['150|Decrement odejmuje, a nie dodaje.','100|Nie jest automatycznie równany do priorytetu R2.','30|To wielkość obniżki, nie wynik.'],'120 − 30 = 90, więc R2 ma wyższy priorytet i przy poprawnym działaniu grupy może przejąć active.')
c('Brama preferowana','Interfejs ma 10.30.0.2/24. Ustaw VIP 10.30.0.1 grupy 30, priorytet 120 i preempt.','R1(config-if)# standby 30 ip {{b0}}\nR1(config-if)# standby 30 priority {{b1}}\nR1(config-if)# standby 30 {{b2}}',[(['10.30.0.1'],'ipv4'),'120','preempt'],'Indywidualny adres interfejsu i wspólny VIP pozostają odrębne.')
c('Śledź fizyczny uplink','Utwórz track 7 dla line-protocol G0/1. Na istniejącej grupie 40 interfejsu G0/0 ustaw obniżkę 25.','R1(config)# track {{b0}} interface GigabitEthernet0/1 {{b1}}\nR1(config-track)# exit\nR1(config)# interface GigabitEthernet0/0\nR1(config-if)# standby 40 track 7 decrement {{b2}}',['7','line-protocol','25'],'Śledzenie line-protocol wykrywa stan interfejsu; nie musi wykryć awarii dalej w sieci.')
q('Dwie aktywne bramy','Oba routery tej samej grupy pokazują active. Jaką kontrolę wykonać w pierwszej kolejności?','Łączność L2 oraz zgodność wersji i parametrów grupy',['Zmienić IP wszystkich hostów na adres broadcast|To zepsuje konfigurację klientów.','Wyłączyć preempt na hostach|Hosty nie konfigurują HSRP preempt.','Zwiększyć numer grupy losowo na jednym routerze|Rozdzieliłoby to konfiguracje zamiast uzgodnić grupę.'],'Brak wymiany komunikatów lub niezgodność grupy może prowadzić do równoczesnego przekonania o roli active.')
c('Zapas z możliwością przejęcia','Na G0/0 R2 ma IP 10.50.0.3/24. Dla grupy 50 ustaw VIP 10.50.0.1, priorytet 100, preempt i pokaż tabelę.','R2(config-if)# standby 50 ip {{b0}}\nR2(config-if)# standby 50 priority {{b1}}\nR2(config-if)# standby 50 {{b2}}\nR2(config-if)# end\nR2# show standby brief',[(['10.50.0.1'],'ipv4'),'100','preempt'],'Zapas z preempt może przejąć rolę, gdy tracking obniży priorytet głównego routera poniżej jego wartości.')
c('Przygotowanie po restarcie','W grupie 60 ustaw priority 130, opóźnij preempt minimum 45 s i wyświetl skrócony stan.','R1(config-if)# standby 60 priority {{b0}}\nR1(config-if)# standby 60 preempt delay minimum {{b1}}\nR1(config-if)# end\nR1# show standby {{b2}}',['130','45','brief'],'Przejęcie należy oceniać razem z gotowością routingu i interfejsów.')
end()
